import { memo, useMemo } from 'react';
import { Animated, Image, StyleSheet, Text, View } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';

import { SharedCountryImage } from '@components/transitions/SharedCountryImage';
import { getStampImage } from '../../assets/stampImages';
import { colors } from '@constants/colors';
import { fonts } from '@constants/typography';
import { useResponsive } from '@hooks/useResponsive';

interface CountryHeroProps {
  displayName: string;
  subregion: string;
  flagEmoji: string;
  /** ISO country code for shared element transition */
  countryCode: string;
  countryImage: ReturnType<typeof require> | null;
  heroHeight: number;
  insetTop: number;
  imageScale: Animated.AnimatedInterpolation<number>;
  imageTranslateY: Animated.AnimatedInterpolation<number>;
  titleScale: Animated.AnimatedInterpolation<number>;
  titleOpacity: Animated.AnimatedInterpolation<number>;
}

function CountryHeroComponent({
  displayName,
  subregion,
  flagEmoji,
  countryCode,
  countryImage,
  heroHeight,
  insetTop,
  imageScale,
  imageTranslateY,
  titleScale,
  titleOpacity,
}: CountryHeroProps) {
  const { isSmallScreen } = useResponsive();
  const stampImage = useMemo(() => getStampImage(countryCode), [countryCode]);

  return (
    <Animated.View
      style={[
        styles.heroBackground,
        {
          height: heroHeight,
          transform: [{ scale: imageScale }, { translateY: imageTranslateY }],
        },
      ]}
    >
      {countryImage ? (
        <Image source={countryImage} style={styles.heroImage} resizeMode="cover" />
      ) : (
        <View style={[styles.heroImage, { backgroundColor: colors.mossGreen }]} />
      )}

      {/* Bottom gradient for sheet transition */}
      <LinearGradient
        colors={['transparent', 'rgba(255, 248, 240, 0.4)', colors.warmCream]}
        locations={[0.6, 0.8, 1]}
        style={styles.heroGradient}
      />

      {/* Title Content - Top Overlay */}
      <Animated.View
        style={[
          styles.heroContent,
          {
            paddingTop: insetTop + 12,
            opacity: titleOpacity,
            transform: [{ scale: titleScale }],
          },
        ]}
      >
        <Text
          style={[styles.countryTitle, isSmallScreen && styles.countryTitleSmall]}
          numberOfLines={2}
          adjustsFontSizeToFit
        >
          {displayName}
        </Text>
        <View style={styles.subregionContainer}>
          <Text style={styles.subregionTextHero}>{subregion}</Text>
          <Text style={styles.flagEmoji}>{flagEmoji}</Text>
        </View>
      </Animated.View>

      {/* Shared element stamp - destination for transition from passport grid */}
      {stampImage && (
        <SharedCountryImage countryId={countryCode} style={styles.sharedStampContainer}>
          <Image source={stampImage} style={styles.sharedStamp} resizeMode="contain" />
        </SharedCountryImage>
      )}
    </Animated.View>
  );
}

export default memo(CountryHeroComponent);

const styles = StyleSheet.create({
  heroBackground: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    zIndex: 0,
  },
  heroImage: {
    width: '100%',
    height: '100%',
  },
  heroGradient: {
    ...StyleSheet.absoluteFillObject,
  },
  heroContent: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: '100%',
    alignItems: 'center',
    justifyContent: 'flex-start',
    paddingHorizontal: 20,
  },
  countryTitle: {
    fontFamily: fonts.oswald.bold,
    fontSize: 56,
    lineHeight: 64,
    color: colors.midnightNavy,
    textAlign: 'center',
    textTransform: 'uppercase',
    textShadowColor: 'rgba(255, 255, 255, 0.6)',
    textShadowOffset: { width: 0, height: 2 },
    textShadowRadius: 8,
    marginBottom: -8,
  },
  countryTitleSmall: {
    fontSize: 44,
    lineHeight: 52,
  },
  subregionContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 8,
  },
  subregionTextHero: {
    fontFamily: fonts.dawning.regular,
    fontSize: 32,
    color: colors.midnightNavy,
    textShadowColor: 'rgba(255, 255, 255, 0.6)',
    textShadowOffset: { width: 0, height: 2 },
    textShadowRadius: 8,
  },
  flagEmoji: {
    fontSize: 28,
    textShadowColor: 'rgba(255, 255, 255, 0.3)',
    textShadowOffset: { width: 0, height: 4 },
    textShadowRadius: 8,
  },
  sharedStampContainer: {
    position: 'absolute',
    bottom: 60,
    right: 20,
    width: 120,
    height: 120,
    // Hidden but positioned for shared element transition endpoint
    opacity: 0,
  },
  sharedStamp: {
    width: '100%',
    height: '100%',
  },
});
